let LANG = "en";
function repairMojibake(root) {
    var repairs = [
        ["ðŸ§®", "🧮"], ["â€”", "—"], ["â†’", "→"], ["â€º", "›"],
        ["â‚¬", "€"], ["Â·", "·"], ["Ã©", "é"], ["Ã«", "ë"],
        ["Ã ", "à"], ["Ã¯", "ï"], ["Ã¶", "ö"], ["Ã¼", "ü"],
    ];
    if (!root) return;
    var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    var node;
    while ((node = walker.nextNode())) {
        if (node.parentElement && /^(SCRIPT|STYLE)$/.test(node.parentElement.tagName)) continue;
        repairs.forEach(function (pair) {
            if (node.nodeValue.indexOf(pair[0]) !== -1)
                node.nodeValue = node.nodeValue.split(pair[0]).join(pair[1]);
        });
    }
}
function setLang(l) {
    LANG = l;
    try {
        localStorage.setItem("sumit_lang", l);
    } catch (e) { }
    var langEn = document.getElementById("lang-en");
    var langNl = document.getElementById("lang-nl");
    if (langEn) langEn.classList.toggle("on", l === "en");
    if (langNl) langNl.classList.toggle("on", l === "nl");
    document.documentElement.lang = l;
    var taalfield = document.getElementById("taalfield");
    if (taalfield) taalfield.value = l;
    document.querySelectorAll("[data-i18n]").forEach((el) => {
        const k = el.getAttribute("data-i18n");
        if (I18N[l][k] !== undefined) el.innerHTML = I18N[l][k];
    });
    document.querySelectorAll("[data-i18n-ph]").forEach((el) => {
        const k = el.getAttribute("data-i18n-ph");
        if (I18N[l][k] !== undefined) el.placeholder = I18N[l][k];
    });
    if (I18N[l].doc_title) document.title = I18N[l].doc_title;
    /* Shared components (invoice gallery) follow window.SUMIT_LANG + "langchange". */
    window.SUMIT_LANG = l;
    try {
        document.dispatchEvent(new CustomEvent("langchange", { detail: l }));
    } catch (e) { }
    /* Signup form and business card use the app's trade list (/js/trades.js). */
    if (window.SumitTrades) {
        SumitTrades.fill(document.getElementById("type"), l);
        var bt = document.getElementById("bctrade-in");
        SumitTrades.fill(bt, l);
        if (bt && !bt.dataset.ready) {
            bt.dataset.ready = "1";
            bt.value = "Schilder";
        }
    }
    if (document.getElementById("bctrade-in")) bcUpdate();
    renderOfferLeft();
    renderLatest();
    if (cap) cap.innerHTML = I18N[LANG]["cap" + cur];
    applyRole();
    wireAllShares();
    repairMojibake(document.body);
}
