/* preload on desktop only once the page is idle, so mobile stays light */
(function () {
    if (
        !window.matchMedia ||
        !window.matchMedia("(min-width:960px)").matches
    )
        return;
    if (
        navigator.connection &&
        (navigator.connection.saveData ||
            /2g/.test(navigator.connection.effectiveType || ""))
    )
        return;
    var go = function () {
        var f = document.getElementById("demoframe");
        if (f && !f.getAttribute("src")) {
            f.onload = function () {
                document.getElementById("demoloading").classList.remove("on");
                fitDemo();
            };
            f.src = f.getAttribute("data-src");
        }
    };
    if (window.requestIdleCallback) {
        requestIdleCallback(go, { timeout: 5000 });
    } else {
        setTimeout(go, 3000);
    }
})();
