async function copyRef() {
    const input = document.getElementById("reflink");
    const btn = document.getElementById("copyRefBtn");

    if (!input) return;

    const link = "sum-it.eu/?ref=JOU4F2";

    // Keep the referral URL fixed
    input.value = link;

    let copied = false;

    /* Modern Clipboard API */
    try {
        if (navigator.clipboard && window.isSecureContext) {
            await navigator.clipboard.writeText(link);
            copied = true;
        }
    } catch (err) {
        copied = false;
    }

    /* Fallback */
    if (!copied) {
        try {
            input.focus();
            input.select();
            input.setSelectionRange(0, input.value.length);

            copied = document.execCommand("copy");

            window.getSelection &&
                window.getSelection().removeAllRanges();
        } catch (err) {
            copied = false;
        }
    }

    /* UX feedback */
    if (btn) {
        btn.classList.toggle("is-copied", copied);

        btn.setAttribute(
            "aria-label",
            copied
                ? "Referral link copied"
                : "Copy referral link"
        );

        if (copied) {
            clearTimeout(btn._copyTimer);

            btn._copyTimer = setTimeout(() => {
                btn.classList.remove("is-copied");

                btn.setAttribute(
                    "aria-label",
                    "Copy referral link"
                );
            }, 1800);
        }
    }

    /* If browser blocks clipboard */
    if (!copied) {
        input.focus();
        input.select();
        input.setSelectionRange(
            0,
            input.value.length
        );
    }
}

/* V24 UX: scroll progress, active section navigation, sticky header state,
mobile CTA and back-to-top. No dependency on the existing site JS. */
(function () {
    var nav = document.querySelector(".nav");
    var topBtn = document.getElementById("v24Top");
    var mobileCta = document.getElementById("v24MobileCta");
    var links = Array.prototype.slice.call(
        document.querySelectorAll('.menu a[href^="#"]'),
    );
    var sections = links
        .map(function (a) {
            return document.querySelector(a.getAttribute("href"));
        })
        .filter(Boolean);
    function sectionOffset(section) {
        var pad = parseFloat(getComputedStyle(document.documentElement).scrollPaddingTop) || 0;
        var margin = parseFloat(getComputedStyle(section).scrollMarginTop) || 0;
        return pad + margin;
    }

    function updateScrollUX() {
        var doc = document.documentElement;
        var max = doc.scrollHeight - window.innerHeight;
        var pct =
            max > 0
                ? Math.min(100, Math.max(0, (window.scrollY / max) * 100))
                : 0;
        document.body.style.setProperty("--scroll-progress", pct + "%");

        var scrolled = window.scrollY > 24;
        if (nav) nav.classList.toggle("is-scrolled", scrolled);
        if (topBtn) topBtn.classList.toggle("show", window.scrollY > 700);
        if (mobileCta)
            mobileCta.classList.toggle("show", window.scrollY > 480);

        /* A clicked section stops at scroll-padding-top + scroll-margin-top
           (174px); compare against that same offset, and take the section
           lowest on the page, so menu order (Team before Blog) can't win. */
        var current = "", best = -Infinity;
        sections.forEach(function (section) {
            var top = section.getBoundingClientRect().top;
            if (top <= sectionOffset(section) + 2 && top > best) {
                best = top;
                current = section.id;
            }
        });
        links.forEach(function (link) {
            link.classList.toggle(
                "active",
                link.getAttribute("href") === "#" + current,
            );
        });
    }

    var ticking = false;
    window.addEventListener(
        "scroll",
        function () {
            if (!ticking) {
                window.requestAnimationFrame(function () {
                    updateScrollUX();
                    ticking = false;
                });
                ticking = true;
            }
        },
        { passive: true },
    );
    window.addEventListener("resize", updateScrollUX);

    links.forEach(function (link) {
        link.addEventListener("click", function () {
            var menu = document.getElementById("mobmenu");
            if (
                menu &&
                menu.classList.contains("open") &&
                typeof closeMenu === "function"
            )
                closeMenu();
        });
    });

    if (topBtn) {
        topBtn.addEventListener("click", function (e) {
            e.preventDefault();
            window.scrollTo({ top: 0, behavior: "smooth" });
        });
    }

    updateScrollUX();
})();

/* Keyboard access for the interactive product mockups: elements marked
   role="button" (projects list, tabs, back) respond to Enter and Space. */
document.addEventListener("keydown", function (e) {
    var el = e.target;
    if (!el || !el.getAttribute || el.getAttribute("role") !== "button") return;
    if (el.tagName === "BUTTON" || el.tagName === "A") return;
    if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        el.click();
    }
});
